// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    address attacker;
    uint256 received;
    uint256 deposited;
    bool private __entered;

    function setUp() public {
        c = new Reentrance();
        attacker = address(this);
    }

    receive() external payable {
        received += msg.value;
        if (!__entered) {
            __entered = true;
            c.withdrawBalance();
        }
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep the domain wide: any positive, non-overflowing deposit
        amount = bound(amount, 1, type(uint96).max);

        attacker = address(this);
        received = 0;
        deposited = amount;
        __entered = false;

        vm.deal(attacker, amount);
        vm.prank(attacker);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = c.getBalance(attacker);

        vm.prank(attacker);
        c.withdrawBalance();

        assertTrue(received <= balanceBefore);
    }
}
